use super::{Model,MoveInputs,TickInputs,Callback};
use crate::modern_lito::{native_roof_callback_study::Inputs,native_roof_callback_study_tests as native,native_appearance_replay_study_tests as fixture,native_appearance_inspection as a,world_map::WorldCell};
use std::{fs,path::Path};use serde_json::{Value,json};
pub(crate) fn input(old:WorldCell,new:WorldCell,clock:u32,samples:Vec<u32>)->MoveInputs{MoveInputs{actor:Inputs{local_actor_pointer_matches:Some(true),old_cell:Some(old),new_cell:Some(new),no_dynamic_cell_entries:Some(true),source_initialized_tiles:Some(true),scheduler_sample_ms:Some(clock)},fresh_schedule_samples:Some(samples)}}
fn tick(clock:u32,samples:Vec<u32>)->TickInputs{TickInputs{timer_removed_before_callback:Some(true),callback_group_matches:Some(true),dispatch_ms:Some(clock),fresh_schedule_samples:Some(samples)}}
fn apply_tick(model:&mut Model<'_>,b:&a::Binding,clock:u32){let ticket=model.next(b,b.observed).unwrap();let prepared=match model.prepare_tick(b,b.observed,&ticket,&tick(clock,vec![])){Ok(p)=>p,Err(e)=>{assert!(e.to_string().contains("Missing source 4D65F0 fresh sample"),"{e}");model.prepare_tick(b,b.observed,&ticket,&tick(clock,vec![clock])).unwrap()}};model.commit(b,b.observed,prepared).unwrap();}
#[test]fn actual_multigroup_midtransition_fifo_duplicate_cancellation_and_local_invalidation(){
 let project=Path::new(env!("CARGO_MANIFEST_DIR"));let fixed=fixture::Fixed::new();let bindings=a::nab(&fixed.bytes("evidence/appearance-bindings.nab")).unwrap();let b=&bindings[3];let(assets,plan,extra)=native::assets();let key=assets.geometry().bindings()[0].key;let sector=assets.geometry().sector(key).unwrap();let(ox,oy)=key.world_origin();let outside=(0..64).flat_map(|y|(0..64).map(move|x|WorldCell{x:ox+x,y:oy+y})).find(|c|!sector.opacity.iter().any(|r|r.x<128&&r.y<64&&i32::from(r.x)==2*(c.x-ox)&&i32::from(r.y)==c.y-oy)).unwrap();let inside=WorldCell{x:ox+51,y:oy+21};let second=WorldCell{x:ox+52,y:oy+16};let mut model=Model::new(true,b,b.observed,&assets,&plan,outside,&input(outside,inside,500,vec![]).actor,64).unwrap();assert_eq!(model.controlled_alias_count(),0);assert_eq!(model.base.alias_counts().0,61);
 let out=project.join("target/r457-multi-roof-cpu");fs::create_dir_all(&out).unwrap();let mut images=Vec::new();let mut rows=Vec::new();let mut capture=|label:&str,model:&Model<'_>|{let canvas=model.render(b,b.observed,inside).unwrap();images.push(fixture::png(&out.join(format!("{label}.png")),canvas.rgba(),512,384));let timers=model.timers(b,b.observed).unwrap();rows.push(json!({"state":label,"timers":timers.iter().map(|t|json!({"at":t.at,"serial":t.serial,"group":t.group,"callback":format!("{:?}",t.callback)})).collect::<Vec<_>>()}));};capture("initial",&model);
 let p=model.prepare_move(b,b.observed,&input(outside,inside,500,vec![500,500])).unwrap();model.commit(b,b.observed,p).unwrap();let timers=model.timers(b,b.observed).unwrap();assert_eq!(timers.iter().map(|t|t.group).collect::<Vec<_>>(),vec![136,168]);assert!(timers.iter().all(|t|t.at==550&&t.callback==Callback::Down));capture("enter-two-source-groups",&model);
 // Repeat the same source record while its first fades are pending. Original
 // 433210 does not cancel existing Down timers; 432F70 cancels all same owner.
 let p=model.prepare_move(b,b.observed,&input(inside,inside,501,vec![501,501])).unwrap();model.commit(b,b.observed,p).unwrap();assert_eq!(model.timers(b,b.observed).unwrap().len(),4);let held_duplicate=model.next(b,b.observed).unwrap();let before=model.timers(b,b.observed).unwrap();let mut bad=tick(550,vec![550]);bad.timer_removed_before_callback=None;assert!(model.prepare_tick(b,b.observed,&held_duplicate,&bad).is_err());assert_eq!(model.timers(b,b.observed).unwrap(),before);apply_tick(&mut model,b,550);assert_eq!(model.timers(b,b.observed).unwrap().iter().filter(|t|t.group==136).count(),1);assert!(model.prepare_tick(b,b.observed,&held_duplicate,&tick(550,vec![550])).is_err());apply_tick(&mut model,b,550);capture("one-dispatch-each-group-cancels-duplicates",&model);
 let before=model.timers(b,b.observed).unwrap();assert!(model.prepare_move(b,b.observed,&input(inside,second,549,vec![549;4])).is_err());assert_eq!(model.timers(b,b.observed).unwrap(),before);let p=model.prepare_move(b,b.observed,&input(inside,second,551,vec![551;4])).unwrap();model.commit(b,b.observed,p).unwrap();let timers=model.timers(b,b.observed).unwrap();assert_eq!(timers.iter().map(|t|(t.group,t.callback)).collect::<Vec<_>>(),vec![(146,Callback::Down),(167,Callback::Down),(136,Callback::Up),(168,Callback::Up)]);assert!(timers.iter().all(|t|t.at==601));capture("midfade-new-groups-old-groups-restore-fifo",&model);
 while let Some(t)=model.timers(b,b.observed).unwrap().first(){let clock=t.at;apply_tick(&mut model,b,clock);}capture("both-group-sets-settled",&model);
 let p=model.prepare_move(b,b.observed,&input(second,outside,900,vec![900;2])).unwrap();model.commit(b,b.observed,p).unwrap();while let Some(t)=model.timers(b,b.observed).unwrap().first(){let clock=t.at;apply_tick(&mut model,b,clock);}capture("all-source-roofs-restored",&model);assert_eq!(images[0]["RGBA_sha256"],images.last().unwrap()["RGBA_sha256"]);
 let p=model.prepare_move(b,b.observed,&input(outside,inside,1200,vec![1200;2])).unwrap();model.commit(b,b.observed,p).unwrap();let stale=model.next(b,b.observed).unwrap();let next_group=stale.timer.group;let before=model.timers(b,b.observed).unwrap();assert!(model.invalidate_group(b,b.observed,next_group,None).is_err());assert_eq!(model.timers(b,b.observed).unwrap(),before);model.invalidate_group(b,b.observed,next_group,Some(true)).unwrap();assert!(model.prepare_tick(b,b.observed,&stale,&tick(1250,vec![1250])).is_err());assert!(model.timers(b,b.observed).unwrap().iter().all(|t|t.group!=next_group));assert!(model.group(b,b.observed,next_group).is_err());model.retire();assert!(model.next(b,b.observed).is_err());assert!(model.render(b,b.observed,inside).is_err());
 fs::write(project.join("logs/continuation-20261003/r457-multi-roof-details.json"),serde_json::to_vec_pretty(&json!({"state":"ACTUAL_MULTIGROUP_MIDFADE_FIFO_TIMER_IDENTITY_AND_LOCAL_RETIREMENT","source_cells":[[inside.x,inside.y],[second.x,second.y]],"source_group_sets":[[136,168],[146,167]],"rows":rows,"images":images,"actual_shared_resident_aliases":61,"actual_controlled_shared_aliases":0,"controlled_shared_alias_mutation_qualified":false,"equal_due_FIFO":true,"duplicate_same_owner_down_canceled_by_callback":true,"midfade_opposite_callback_canceled":true,"failed_prepare_atomic":true,"held_timer_reuse_refused":true,"private_prepared_revision":true,"restored_RGBA_equals_initial":true,"local_group_invalidation_clears_matching_timers":true,"original_group_unload_timer_cancellation_unqualified":true,"original_4835D0_frees_groups_without_visible_timer_cancel":true,"runtime_inputs_observed":false,"renderer_LOADED":false,"GUI":0,"input_pins":fixed.used.into_inner(),"extra_input_pins":extra})).unwrap()).unwrap();
}
